      if (atlasSel && AM.vg.P[atlasSel]) { const g = AM.vg.P[atlasSel]; AM.fit(g.mb, !newView, .6, (AM.vg.box[2] - AM.vg.box[0]) * .18); if (g.size * AM.s < 30) AM.pulse = { id: atlasSel, t0: performance.now(), d: 2400 }; }
